async function buildFlow(page, v, y, fontScale = 1) {
    const mobile = v.mode === "touch", s = mobile ? Math.min(v.width / L.base_width, v.height / L.base_height) : 1;
    const w = v.width / s, h = v.height / s, ins = v.safe_insets.map(n => n / s), safe = { x: ins[0], y: ins[1], w: w - ins[0] - ins[2], h: h - ins[1] - ins[3] };
    const suffix = fontScale > 1 ? " / text125" : "";
    const menu = frame(page, v.id + suffix + " / Menu", 0, y, w, h), play = frame(page, v.id + suffix + " / Play", v.width + 80, y, w, h), pause = frame(page, v.id + suffix + " / Pause", 2 * (v.width + 80), y, w, h);
    for (const f of [menu, play, pause]) {
        sceneProxy(f, w, h);
        f.setPluginData("tt.viewport", JSON.stringify({ view: v, scale: s, logical: [w, h], text_scale: fontScale, scope: "editable Figma framing mock; not engine capture" }));
    }
    const title = card(play, "Objective", "Milk Harbor", "Sail through the shallows.", safe.x + (mobile ? 24 : 28), safe.y + (mobile ? 16 : 24), mobile ? L.touch_objective_width : 330, mobile, fontScale);
    title.name = "Objective";
    const targetCard = card(play, "Target", "Cargo parcel", "A smaller parcel lets the raft float higher.", mobile ? safe.x + safe.w / 2 - 250 : 28, mobile ? safe.y + safe.h - 260 : h - 210, mobile ? 500 : 380, mobile, fontScale);
    if (mobile)
        targetCard.y = safe.y + safe.h - 120 - targetCard.height;
    let pauseButton;
    if (mobile) {
        const endX = safe.x + safe.w, endY = safe.y + safe.h, mid = safe.x + safe.w / 2;
        pauseButton = instanceButton(play, "Pause", endX - 164, safe.y + 16, 140, 88, true, "Normal", fontScale);
        instanceButton(play, "Hint", endX - 328, safe.y + 16, 140, 88, true, "Normal", fontScale);
        instanceButton(play, "Target", endX - 164, safe.y + 116, 140, 88, true, "Normal", fontScale);
        instanceButton(play, "Use", endX - 212, endY - 208, 188, 88, true, "Normal", fontScale);
        instanceButton(play, "Hop", endX - 212, endY - 108, 188, 88, true, "Normal", fontScale);
        ["Small", "Normal", "Large"].forEach((label, i) => instanceButton(play, label, mid - 207 + i * 142, endY - 112, 130, 88, true, i === 1 ? "Selected" : "Normal", fontScale));
        const pad = figma.createEllipse();
        play.appendChild(pad);
        pad.name = "Movement pad / radius88";
        pad.resize(176, 176);
        pad.x = safe.x + 34;
        pad.y = endY - 208;
        pad.fills = [paint(C.cream)];
        pad.strokes = [paint(C.teal)];
        pad.strokeWeight = 3;
        const knob = figma.createEllipse();
        play.appendChild(knob);
        knob.resize(68, 68);
        knob.x = pad.x + 54;
        knob.y = pad.y + 54;
        knob.fills = [paint(C.teal)];
    }
    else {
        pauseButton = instanceButton(play, "Pause", w - 148, 26, 120, 44, false);
        ["1 Small", "2 Normal", "3 Large"].forEach((label, i) => instanceButton(play, label, 45 + i * 113, h - 102, 106, 34, false, i === 1 ? "Selected" : "Normal"));
        text(play, "W/A/S/D Move     Space Hop     E Board / Sail     Tab Target     Q/F Resize     H Hint", 200, h - 30, w - 400, T.desktop_footer);
    }
    const menuW = mobile ? Math.min(L.touch_menu_max_width, safe.w - 64) : L.desktop_menu_width;
    const bx = safe.x + (safe.w - menuW) / 2, by = safe.y + 20;
    function menuPanel(target, heading) {
        const dim = rect(target, "Pause scrim", 0, 0, w, h, "#213133");
        dim.opacity = .36;
        const scroll = frame(target, "Safe menu scroll region", safe.x + 20, safe.y + 20, safe.w - 40, safe.h - 40);
        scroll.fills = [];
        scroll.overflowDirection = "VERTICAL";
        const panelHeight = mobile ? 620 : 440;
        const panel = frame(scroll, "Menu panel", bx - (safe.x + 20), Math.max(0, (safe.h - 40 - panelHeight) / 2), menuW, panelHeight);
        panel.cornerRadius = 25;
        text(panel, "TINY TROUBLE", 32, 24, menuW - 64, mobile ? 24 : 13, C.teal);
        const t = text(panel, heading, 32, 68, menuW - 64, mobile ? 40 * fontScale : 42);
        return { panel, top: t.y + t.height + 24, bw: menuW - 64 };
    }
    const m = menuPanel(menu, "Milk Harbor"), p = menuPanel(pause, "A little breather");
    const btnH = mobile ? 88 : 48, gap = 12;
    const start = instanceButton(m.panel, "Take a little step →", 32, m.top, m.bw, btnH, mobile, "Focus", fontScale);
    text(m.panel, "A cereal loop. A precious little parcel.", 32, m.top + btnH + 20, m.bw, mobile ? 24 * fontScale : 18);
    const resume = instanceButton(p.panel, "Back to Pip", 32, p.top, p.bw, btnH, mobile, "Focus", fontScale);
    const returnTitle = instanceButton(p.panel, "Save & return to title", 32, p.top + btnH + gap, p.bw, btnH, mobile, "Normal", fontScale);
    text(p.panel, "Reduced motion\nMusic   ━━━━━   Effects   ━━━━━\nText size   100% — 125%", 32, p.top + 2 * (btnH + gap), p.bw, mobile ? 24 * fontScale : 18);
    await link(start, play, "Menu → Play");
    await link(pauseButton, pause, "Play → Pause");
    await link(resume, play, "Pause → Play");
    await link(returnTitle, menu, "Pause → Menu");
    for (const f of [menu, play, pause])
        f.rescale(s);
    text(page, `${v.id}${suffix}: ${v.width} × ${v.height}; ${mobile ? "simulated safe insets " + v.safe_insets.join("/") : "desktop baseline"}. Editable framing mock, engine reference kept separately.`, 0, y - 40, 3 * (v.width + 80), 18);
    return menu;
}
async function main() {
    const available = await figma.listAvailableFontsAsync();
    const match = available.find(f => f.fontName.family === T.family && /semi.?bold|600/i.test(f.fontName.style));
    if (match)
        FONT = match.fontName;
    else {
        FONT = { family: "Inter", style: "Medium" };
    }
    await figma.loadFontAsync(FONT);
    const page = figma.createPage();
    page.name = "Tiny Trouble / TT-027 / " + TT_TOKEN_HASH.slice(0, 8);
    await figma.setCurrentPageAsync(page);
    page.setPluginData("tt.tokens", JSON.stringify(TT_TOKENS));
    page.setPluginData("tt.token_hash", TT_TOKEN_HASH);
    page.setPluginData("tt.font_status", FONT.family === T.family ? "Nunito semibold available" : "Fallback Inter; font parity NOT verified");
    for (const key of ["desktop_body", "desktop_objective", "desktop_target_title", "desktop_target_help", "touch_body_min", "touch_objective"]) {
        const style = figma.createTextStyle();
        style.name = "Tiny Trouble/" + key;
        style.fontName = FONT;
        style.fontSize = T[key];
        style.lineHeight = { unit: "PERCENT", value: 140 };
    }
    const board = frame(page, "01 Art direction / concepts versus engine", 0, 0, 1720, 1510);
    text(board, "Tiny Trouble · a breakfast world you can touch", 40, 32, 1600, 40);
    text(board, "Warm cream, amber crumbs, coral thread and teal actions. Rounded toy shapes; quiet rough surfaces; readable silhouettes.", 40, 100, 1600, 24);
    let x = 40;
    for (const [name, value] of Object.entries(C)) {
        rect(board, name, x, 162, 156, 65, value, 10);
        text(board, name + "\n" + value, x, 234, 160, 16);
        const style = figma.createPaintStyle();
        style.name = "Tiny Trouble/" + name;
        style.paints = [paint(value)];
        x += 180;
    }
    text(board, `Type: ${T.family} ${T.weight}. Actual Figma font: ${FONT.family} / ${FONT.style}.`, 40, 314, 1600, 24);
    image(board, "concept_sheet", 40, 370, 790, 430);
    image(board, "concept_target", 890, 370, 790, 430);
    text(board, "GENERATED CONCEPT · aspirational art sheet", 40, 815, 790, 20, C.teal);
    text(board, "GENERATED CONCEPT · aspirational target", 890, 815, 790, 20, C.teal);
    image(board, "runtime_desktop", 40, 884, 790, 444);
    image(board, "runtime_phone", 890, 884, 790, 365);
    text(board, "ENGINE CAPTURE · packaged desktop 0.2.2", 40, 1340, 790, 20, C.teal);
    text(board, "ENGINE CAPTURE · source 0.2.5 phone simulation · text1.25", 890, 1270, 790, 20, C.teal);
    text(board, "Concepts describe direction; engine captures establish actual output. Physical iOS layout, Figma font rendering and full responsive parity require separate verification.", 40, 1410, 1600, 22);
    const compBoard = frame(page, "02 Reusable components", 1800, 0, 1640, 1510);
    text(compBoard, "Native UI vocabulary", 32, 24, 1400, 36);
    const all = [];
    let row = 0;
    for (const mode of ["Desktop", "Touch"]) {
        let col = 0;
        for (const state of ["Normal", "Hover", "Pressed", "Focus", "Selected", "Disabled"]) {
            const b = baseButton(mode, state);
            compBoard.appendChild(b);
            b.x = 32 + col * 262;
            b.y = 100 + row * 180;
            buttonMasters[mode + state] = b;
            all.push(b);
            col++;
        }
        row++;
    }
    const set = figma.combineAsVariants(all, compBoard);
    set.name = "Button";
    const cards = [];
    for (const [kind, index] of ["Objective", "Target", "Toast"].map((v, i) => [v, i])) {
        const width = kind === "Toast" ? L.touch_toast_width : 500;
        const c = figma.createComponent();
        compBoard.appendChild(c);
        c.name = "Kind=" + kind;
        c.x = 32 + index * 530;
        c.y = 550;
        c.resize(width, 150);
        c.layoutMode = "VERTICAL";
        c.primaryAxisSizingMode = "AUTO";
        c.counterAxisSizingMode = "FIXED";
        c.paddingTop = 20;
        c.paddingBottom = 20;
        c.paddingLeft = 20;
        c.paddingRight = 20;
        c.itemSpacing = 6;
        c.fills = [paint(C.cream)];
        c.cornerRadius = 18;
        if (kind === "Toast")
            c.minHeight = L.touch_toast_min_height;
        else {
            const title = text(c, kind, 0, 0, width - 40, 24);
            title.name = "Title";
        }
        const body = text(c, "One clear next step for Pip.", 0, 0, width - 40, 24);
        body.name = "Body";
        cardMasters[kind] = c;
        cards.push(c);
    }
    const cardSet = figma.combineAsVariants(cards, compBoard);
    cardSet.name = "Card";
    text(compBoard, "Components use editable text and Auto Layout. Focus retains ink text; teal hover/pressed states use cream text. Selected is distinct from focused. Touch controls: ≥88 logical units; text24–30 at scale1–1.25. Toast: width480, minimum height90. Runtime places toasts around actor/action obstacles, shifts the persistent target card horizontally around Pip/controls, and refits shorter copy. Prototype frames do not simulate this movement; human motion review is pending.", 32, 830, 1520, 24);
    text(compBoard, "Prototype frames are logical-canvas reconstructions with an editable scene proxy, not claimed Figma exports or gameplay. Navigation links: Menu → Play → Pause → Resume / Title. Safe insets are design inputs, not measured device values.", 32, 1030, 1520, 24);
    studyBoard(page);
    workshopBoard(page);
    const starts = [];
    let y = 1700;
    for (const v of TT_TOKENS.reference_viewports) {
        starts.push(await buildFlow(page, v, y));
        y += v.height + 140;
    }
    const compact = TT_TOKENS.reference_viewports.find(v => v.id === "phone_compact");
    starts.push(await buildFlow(page, compact, y, 1.25));
    page.flowStartingPoints = starts.map(node => ({ nodeId: node.id, name: node.name }));
    page.setPluginData("tt.prototype_links", JSON.stringify(links));
    figma.viewport.scrollAndZoomIntoView([board]);
    figma.currentPage.selection = [board];
    figma.closePlugin(`Created Tiny Trouble boards, 2 component sets and ${starts.length} navigation flows. ${FONT.family === T.family ? "Nunito loaded." : "Inter fallback: verify Nunito before approval."}`);
}
main().catch(error => { figma.closePlugin("Tiny Trouble import incomplete: " + String(error)); });
